import { test, expect } from '@playwright/test';

test.describe('File Upload - Unsupported File Type Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display error message when uploading unsupported file type', async ({ page }) => {
    // Intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.abort('unsupported file type');
    });

    // Set up file input using getByLabel
    const fileInput = page.getByLabel('Upload file');
    await expect(fileInput).toBeVisible();

    // Set up file input using getByRole
    const fileInputRole = page.getByRole('button', { name: /upload file/i });
    await expect(fileInputRole).toBeVisible();

    // Set up file input using getByText
    const fileInputText = page.getByText('Select file');
    await expect(fileInputText).toBeVisible();

    // Set up error message using getByText
    const errorMessage = page.getByText('Unsupported file type');
    await expect(errorMessage).toBeVisible();

    // Set up success message using getByText
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).not.toBeVisible();

    // Set up file input to upload a .txt file
    await fileInput.setInputFiles('fixtures/unsupported-file.txt');

    // Verify error message is displayed
    await expect(errorMessage).toBeVisible();

    // Verify success message is not displayed
    await expect(successMessage).not.toBeVisible();

    // Verify file input is still visible
    await expect(fileInput).toBeVisible();
  });

  test('should not display error message when uploading supported file type', async ({ page }) => {
    // Intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Set up file input using getByLabel
    const fileInput = page.getByLabel('Upload file');
    await expect(fileInput).toBeVisible();

    // Set up file input using getByRole
    const fileInputRole = page.getByRole('button', { name: /upload file/i });
    await expect(fileInputRole).toBeVisible();

    // Set up file input using getByText
    const fileInputText = page.getByText('Select file');
    await expect(fileInputText).toBeVisible();

    // Set up success message using getByText
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).toBeVisible();

    // Set up file input to upload a supported .pdf file
    await fileInput.setInputFiles('fixtures/supported-file.pdf');

    // Verify error message is not displayed
    await expect(errorMessage).not.toBeVisible();

    // Verify success message is displayed
    await expect(successMessage).toBeVisible();

    // Verify file input is still visible
    await expect(fileInput).toBeVisible();
  });
});
